1	package oci
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"strings"
12		"time"
13	)
14	
15	// registryHTTPClient is swapped by tests that must reach a stand-in for a
16	// registry by another address.
17	var registryHTTPClient = &http.Client{
18		Timeout:       15 * time.Second,
19		CheckRedirect: refuseOffOriginRedirect,
20	}
21	
22	// maxRedirects is net/http's default limit, kept now that CheckRedirect is set.
23	const maxRedirects = 10
24	
25	// refuseOffOriginRedirect keeps credentials on the origin they were meant for.
26	// It compares with the initial request (via[0]), not only the previous hop, so
27	// a chain that leaves the origin and comes back is refused too. The redirect is
28	// refused rather than followed without Authorization: a registry that moves
29	// content to another host is misconfigured for this client, and an explicit
30	// error is safer than a silent anonymous retry.
31	func refuseOffOriginRedirect(req *http.Request, via []*http.Request) error {
32		if len(via) >= maxRedirects {
33			return fmt.Errorf("stopped after %d redirects", maxRedirects)
34		}
35		if !sameOrigin(via[0].URL.String(), req.URL.String()) {
36			return fmt.Errorf("%w (%s)", errOffOriginRedirect, req.URL.Host)
37		}
38		return nil
39	}
40	
41	// errOffOriginRedirect is the refusal refuseOffOriginRedirect returns.
42	var errOffOriginRedirect = errors.New("refusing redirect to another origin")
43	
44	// ErrTagsNextOffOrigin is returned by ListRegistryTagsContext when a page's
45	// Link rel="next" points to another origin. The list is not returned partial:
46	// a short list would pass for the whole one.
47	var ErrTagsNextOffOrigin = errors.New("tag list continues on another origin")
48	
49	// redirectRefusal strips the target URL from a refused redirect. net/http wraps
50	// the refusal in a *url.Error carrying the full target URL, which may hold a
51	// signed query; only the meaning and the host (kept by the refusal itself)
52	// remain. Other errors pass through unchanged.
53	func redirectRefusal(err error) error {
54		var ue *url.Error
55		if errors.As(err, &ue) && errors.Is(ue.Err, errOffOriginRedirect) {
56			return ue.Err
57		}
58		return err
59	}
60	
61	const (
62		// maxTagPages bounds how many pages of a tag list are followed. A registry
63		// that pages (`?n=`, `Link: rel="next"`) answers a page at a time, and one
64		// that keeps answering "next" must not hold a caller forever.
65		maxTagPages = 100
66		// maxTagResponse bounds one page. Docker Hub answers a whole list in one
67		// response when no page size is given — measured at 9 125 tags for
68		// library/node (§3.2) — so the bound is generous, but it is a bound.
69		maxTagResponse = 32 << 20
70		// maxTokenResponse bounds a Bearer token endpoint's answer; a token is a
71		// few KiB, so a larger body is an error, not a silent cut.
72		maxTokenResponse = 1 << 20
73	)
74	
75	// StatusSource says which endpoint answered with a non-success status.
76	type StatusSource int
77	
78	const (
79		// SourceRegistry is the registry's v2 API.
80		SourceRegistry StatusSource = iota
81		// SourceToken is the Bearer token endpoint.
82		SourceToken
83	)
84	
85	// StatusError is a registry or token endpoint answering with a non-success
86	// status. Failures that are not a status (unreadable body, missing realm, no
87	// token field) are plain errors.
88	type StatusError struct {
89		Code   int
90		Source StatusSource
91		// Challenge is the Www-Authenticate header of a 401 whose challenge is not
92		// Bearer; empty otherwise.
93		Challenge string
94		// unexpectedChallenge tells that 401 apart from a 401 answered after a
95		// token exchange, so Error() keeps both historical messages.
96		unexpectedChallenge bool
97	}
98	
99	// Error returns the message the plain errors carried before the type existed.
100	func (e *StatusError) Error() string {
101		switch {
102		case e.Source == SourceToken:
103			return fmt.Sprintf("token endpoint returned %d", e.Code)
104		case e.unexpectedChallenge:
105			return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
106		}
107		return fmt.Sprintf("registry returned %d", e.Code)
108	}
109	
110	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
111	//
112	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
113	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
114	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
115	// The token is kept for the following pages.
116	//
117	// The list is followed across pages: whatever a registry caps a response at,
118	// and Docker Hub does not, a repository with more tags than one page holds is
119	// returned whole. This is the one tag lister that speaks the Bearer flow; the
120	// template client's ListTags (Client.ListTags) reads a registry the user
121	// configured for templates and only ever sends Basic auth.
122	func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
123		return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
124	}
125	
126	// ListRegistryTagsContext is ListRegistryTags bound to ctx: a cancelled or
127	// expired context stops the walk, including a request in flight, and the
128	// returned error wraps the context's error. A context already done sends
129	// nothing. registryHTTPClient's own timeout still applies per request; when
130	// both expire, whichever comes first ends the request, and either way the
131	// error satisfies errors.Is(err, context.DeadlineExceeded).
132	func ListRegistryTagsContext(ctx context.Context, apiURL, repo, username, password string) ([]string, error) {
133		next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
134		var (
135			tags  []string
136			token string
137		)
138		for page := 0; next != ""; page++ {
139			if page == maxTagPages {
140				return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
141			}
142			body, link, usedToken, err := registryGETContext(ctx, next, username, password, token)
143			if err != nil {
144				return nil, err
145			}
146			token = usedToken
147			var result struct {
148				Tags []string `json:"tags"`
149			}
150			if err := json.Unmarshal(body, &result); err != nil {
151				return nil, fmt.Errorf("decode tags response: %w", err)
152			}
153			tags = append(tags, result.Tags...)
154			current := next
155			if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
156				// Never send credentials to another origin, and never pass a
157				// partial list off as the whole one. Only the host is named.
158				return nil, fmt.Errorf("%w (%s)", ErrTagsNextOffOrigin, hostOf(next))
159			}
160		}
161		return tags, nil
162	}
163	
164	// registryGET performs a GET, answering a Bearer challenge once. It returns the
165	// body, the Link header, and the token to send on the following requests.
166	func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
167		return registryGETContext(context.Background(), rawURL, username, password, token)
168	}
169	
170	// registryGETContext is registryGET bound to ctx.
171	func registryGETContext(ctx context.Context, rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
172		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
173		if err != nil {
174			return nil, "", token, err
175		}
176		defer func() { _ = resp.Body.Close() }()
177		if resp.StatusCode != http.StatusOK {
178			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
179		}
180		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
181		return body, resp.Header.Get("Link"), token, err
182	}
183	
184	// registryDo sends one request, answering a Bearer challenge once. The caller
185	// closes the response body and reads the status.
186	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
187		return registryDoContext(context.Background(), method, rawURL, accept, username, password, token)
188	}
189	
190	// registryDoContext is registryDo bound to ctx.
191	func registryDoContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
192		resp, err := doRequestContext(ctx, method, rawURL, accept, username, password, token)
193		if err != nil {
194			return nil, token, err
195		}
196		if resp.StatusCode != http.StatusUnauthorized {
197			return resp, token, nil
198		}
199		challenge := resp.Header.Get("Www-Authenticate")
200		_ = resp.Body.Close()
201		if !strings.HasPrefix(challenge, "Bearer ") {
202			return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
203		}
204		token, err = exchangeBearerTokenContext(ctx, challenge[7:], username, password)
205		if err != nil {
206			return nil, "", err
207		}
208		if resp, err = doRequestContext(ctx, method, rawURL, accept, "", "", token); err != nil {
209			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, rawURL, err)
210		}
211		return resp, token, nil
212	}
213	
214	// doRequest sends one request: a bearer token when there is one, Basic auth
215	// when there are credentials and no token.
216	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
217		return doRequestContext(context.Background(), method, rawURL, accept, username, password, token)
218	}
219	
220	// doRequestContext is doRequest bound to ctx; a context already done sends
221	// nothing.
222	func doRequestContext(ctx context.Context, method, rawURL, accept, username, password, token string) (*http.Response, error) {
223		req, err := http.NewRequestWithContext(ctx, method, rawURL, nil)
224		if err != nil {
225			return nil, fmt.Errorf("build request: %w", err)
226		}
227		if accept != "" {
228			req.Header.Set("Accept", accept)
229		}
230		switch {
231		case token != "":
232			req.Header.Set("Authorization", "Bearer "+token)
233		case username != "" && password != "":
234			req.SetBasicAuth(username, password)
235		}
236		resp, err := registryHTTPClient.Do(req)
237		if err != nil {
238			return nil, fmt.Errorf("%s %s: %w", method, rawURL, redirectRefusal(err))
239		}
240		return resp, nil
241	}
242	
243	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
244	// tag is an index (or a Docker manifest list), and its digest is the one `docker
245	// pull` records in RepoDigests; asking for a single-platform manifest only
246	// would make the registry convert or refuse, and the digests would not match.
247	var manifestAccept = strings.Join([]string{
248		"application/vnd.oci.image.index.v1+json",
249		"application/vnd.docker.distribution.manifest.list.v2+json",
250		"application/vnd.oci.image.manifest.v1+json",
251		"application/vnd.docker.distribution.manifest.v2+json",
252	}, ", ")
253	
254	// ManifestDigest returns the digest a tag currently points to, from the
255	// registry's Docker-Content-Digest header.
256	//
257	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
258	// limit, and nothing but the header is needed.
259	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
260		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
261		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
262		if err != nil {
263			return "", err
264		}
265		_ = resp.Body.Close()
266		if resp.StatusCode != http.StatusOK {
267			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
268		}
269		digest := resp.Header.Get("Docker-Content-Digest")
270		if digest == "" {
271			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
272		}
273		return digest, nil
274	}
275	
276	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
277	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
278	// everything else over HTTPS. An empty registry is Docker Hub.
279	func RegistryAPIBase(registry string) string {
280		switch {
281		case registry == "":
282			return "https://registry-1.docker.io"
283		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
284			return "http://" + registry
285		}
286		return "https://" + registry
287	}
288	
289	// hostOf is the host of rawURL, or "" when it does not parse.
290	func hostOf(rawURL string) string {
291		u, err := url.Parse(rawURL)
292		if err != nil {
293			return ""
294		}
295		return u.Host
296	}
297	
298	// resolveNext is the URL a Link header's rel="next" points to, resolved against
299	// the page it came with — registries send it as a path — or "" when there is
300	// none. A next link that leads back to the page just read ends the walk rather
301	// than looping on it.
302	func resolveNext(current, link string) string {
303		for _, part := range strings.Split(link, ",") {
304			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
305			if !ok || !strings.Contains(rel, `rel="next"`) {
306				continue
307			}
308			target = strings.Trim(strings.TrimSpace(target), "<>")
309			base, err := url.Parse(current)
310			if err != nil {
311				return ""
312			}
313			ref, err := url.Parse(target)
314			if err != nil {
315				return ""
316			}
317			if next := base.ResolveReference(ref).String(); next != current {
318				return next
319			}
320		}
321		return ""
322	}
323	
324	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
325	func exchangeBearerToken(challenge, username, password string) (string, error) {
326		return exchangeBearerTokenContext(context.Background(), challenge, username, password)
327	}
328	
329	// exchangeBearerTokenContext is exchangeBearerToken bound to ctx.
330	func exchangeBearerTokenContext(ctx context.Context, challenge, username, password string) (string, error) {
331		params := parseBearerChallenge(challenge)
332		realm, ok := params["realm"]
333		if !ok {
334			return "", fmt.Errorf("bearer challenge missing realm")
335		}
336		u, err := url.Parse(realm)
337		if err != nil {
338			return "", fmt.Errorf("parse realm %q: %w", realm, err)
339		}
340		q := u.Query()
341		if s, ok := params["service"]; ok {
342			q.Set("service", s)
343		}
344		if s, ok := params["scope"]; ok {
345			q.Set("scope", s)
346		}
347		u.RawQuery = q.Encode()
348	
349		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
350		if err != nil {
351			return "", fmt.Errorf("build token request: %w", err)
352		}
353		if username != "" && password != "" {
354			req.SetBasicAuth(username, password)
355		}
356		resp, err := registryHTTPClient.Do(req)
357		if err != nil {
358			return "", fmt.Errorf("fetch token: %w", redirectRefusal(err))
359		}
360		defer func() { _ = resp.Body.Close() }()
361		if resp.StatusCode != http.StatusOK {
362			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
363		}
364		body, err := io.ReadAll(io.LimitReader(resp.Body, maxTokenResponse+1))
365		if err != nil {
366			return "", fmt.Errorf("read token response: %w", err)
367		}
368		if len(body) > maxTokenResponse {
369			return "", fmt.Errorf("token response over %d bytes", maxTokenResponse)
370		}
371		var result struct {
372			Token       string `json:"token"`
373			AccessToken string `json:"access_token"`
374		}
375		if err := json.Unmarshal(body, &result); err != nil {
376			return "", fmt.Errorf("decode token response: %w", err)
377		}
378		if result.Token != "" {
379			return result.Token, nil
380		}
381		if result.AccessToken != "" {
382			return result.AccessToken, nil
383		}
384		return "", fmt.Errorf("token response contained no token field")
385	}
386	
387	// parseBearerChallenge parses the value portion of a Www-Authenticate: Bearer header.
388	// Example: `realm="https://auth.docker.io/token",service="registry.docker.io"`
389	func parseBearerChallenge(s string) map[string]string {
390		params := make(map[string]string)
391		for _, part := range strings.Split(s, ",") {
392			part = strings.TrimSpace(part)
393			idx := strings.IndexByte(part, '=')
394			if idx < 0 {
395				continue
396			}
397			key := strings.TrimSpace(part[:idx])
398			val := strings.Trim(strings.TrimSpace(part[idx+1:]), `"`)
399			params[key] = val
400		}
401		return params
402	}
