			defer s.Close()
			got, err := ListRegistryTagsContext(context.Background(), s.URL, "x", "user", "pass")
			if err != nil {
				t.Fatal(err)
			}
			if strings.Join(got, ",") != "a,b" {
				t.Errorf("tags = %v, want [a b]", got)
			}
		})
